sys_script_fix.script:
function setTaskAgileStoryColumnReadOnly() {
	var gr = new GlideRecord('sys_dictionary');

	gr.addQuery('name', 'task');
	gr.addQuery('element', 'agile_story');
	gr.addQuery('read_only', false);
	gr.query();

	if (gr.next()) {
		gr.setValue('read_only', true);

		if (gr.update())
			gs.info('Column agile_story in task table has been set as read-only');
	}
}

setTaskAgileStoryColumnReadOnly();
